import{z as n,x as m,o as A,c as s,q as i,j as l,D as e,d as E,s as o,S as B,b as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"值迭代与策略迭代","description":"","frontmatter":{"title":"值迭代与策略迭代","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/value-policy-iteration.md","filePath":"llm/value-policy-iteration.md","lastUpdated":1791063341000}'),p={name:"llm/value-policy-iteration.md"};function d(D,a,g,_,C,c){const t=m("Mermaid");return A(),s("div",null,[a[2]||(a[2]=i('<h1 id="值迭代与策略迭代" tabindex="-1">值迭代与策略迭代 <a class="header-anchor" href="#值迭代与策略迭代" aria-label="Permalink to &quot;值迭代与策略迭代&quot;">​</a></h1><div class="epigraph"><p>先评估你现在的做法，再在每个状态换上更好的动作；两步交替到不动，就是最优——前提是转移和奖励写在你的手里。</p><footer>—— 据 Bellman, Dynamic Programming, 1957；策略迭代见 Howard, Dynamic Programming and Markov Processes, 1960；Sutton &amp; Barto 2018 第 4 章整理</footer></div><p><a href="/llm/bellman-equations-rl">上一课</a>把 \\(V^\\pi\\) 与 \\(V^*\\) 证明成压缩算子的唯一不动点、从任意初值迭代必收敛；但那只给出「极限存在」，没有给出算法的组织：评估该用哪支方程、何时换策略、迭代到什么时候停。本课补齐：策略评估、策略改进、策略迭代与值迭代，收敛速度与停止判据；最后指出这一切的前提「模型已知」在 LLM 里几乎不成立，为无模型单元铺路。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>价值与最优价值的方程有了，怎么把它们变成程序？天真的做法是枚举策略逐一评估再比较——策略随状态数指数多，枚举不可行。真正可用的组织只有两个迭代：一支只逼近当前策略的价值（评估），一支在每个状态贪心地换动作（改进）。怎么交替、各自多快、何时敢停，是本课的问题。</p><p><span class="marginnote">直觉类比：策略迭代像「先完整复盘这盘棋现在下到什么水平，再据此把每一步换成更好的走法」；值迭代像「每想一步，就当场按最优标准修正这步的价值」。前者轮次少但每次复盘贵，后者每步都轻、但要磨很多轮。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>策略迭代</strong>循环两步。其一，策略评估：解 \\(T_{\\pi_k}\\) 的不动点，得 \\(V^{\\pi_k}\\)——直接解线性方程组，或内层迭代到收敛。其二，策略改进：对每个状态贪心，</p> \\[\\pi_{k+1}(s)=\\arg\\max_a\\Big[r(s,a)+\\gamma\\sum_{s&#39;}P(s&#39;\\mid s,a)V^{\\pi_k}(s&#39;)\\Big] \\]<p>策略改进定理保证换法不降价值：\\(V^{\\pi_{k+1}}\\ge V^{\\pi_k}\\) 逐状态成立；若处处无改进，当前策略已对 \\(V^*\\) 贪心，即最优。有限状态与动作下策略只有有限个、每次改进严格变好，所以策略迭代<strong>有限步</strong>终止。</p><p><strong>值迭代</strong>不区分两步，直接对最优算子做不动点迭代 \\(v_{k+1}=T^*v_k\\)；它可以读成「评估只做一步的策略迭代」，也可读成逐状态套用最优方程。轮数上每轮误差至少乘 \\(\\gamma\\)；停止判据要经过几何级数折算：</p> \\[\\|v_k-v_{k-1}\\|_\\infty\\lt\\frac{\\varepsilon(1-\\gamma)}{\\gamma}\\quad\\Longrightarrow\\quad\\|v_k-V^*\\|_\\infty\\lt\\varepsilon \\]<p><span class="marginnote">数字实例：\\(\\gamma=0.9\\) 时每轮误差至少缩成上一轮的 0.9 倍，压到百分之一约需 \\(\\ln 0.01/\\ln 0.9\\approx 44\\) 轮；\\(\\gamma=0.99\\) 时同样的精度要约 459 轮。折扣因子越接近 1，值迭代的轮数惩罚越狠。</span></p>',13)),(A(),l(B,null,{default:e(()=>[o(t,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20PI0%5B%22%E5%88%9D%E5%A7%8B%E5%8C%96%E7%AD%96%E7%95%A5%20pi_0%22%5D%20--%3E%20EVAL%5B%22%E7%AD%96%E7%95%A5%E8%AF%84%E4%BC%B0%EF%BC%9A%E8%A7%A3%20T_pi%20%E7%9A%84%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A%20%20EVAL%20--%3E%20IMP%5B%22%E7%AD%96%E7%95%A5%E6%94%B9%E8%BF%9B%EF%BC%9A%E5%AF%B9%20V%20%E8%B4%AA%E5%BF%83%22%5D%0A%20%20IMP%20--%3E%20CHK%7B%22%E5%A4%84%E5%A4%84%E6%97%A0%E6%94%B9%E8%BF%9B%3F%22%7D%0A%20%20CHK%20--%3E%7C%E5%90%A6%7C%20EVAL%0A%20%20CHK%20--%3E%7C%E6%98%AF%7C%20OPT%5B%22%E6%9C%80%E4%BC%98%E7%AD%96%E7%95%A5%20pi*%22%5D%0A%20%20ALT%5B%22%E5%80%BC%E8%BF%AD%E4%BB%A3%EF%BC%9A%E5%8F%8D%E5%A4%8D%20v%20%3D%20T*%20v%EF%BC%8C%E6%8A%8A%E4%B8%A4%E6%AD%A5%E6%8A%98%E6%88%90%E4%B8%80%E6%AD%A5%22%5D%20--%3E%20OPT%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[E("两支迭代的分工来自成本结构。策略迭代每轮要解一个 \\(|S|\\) 元方程组，但轮数对 \\(\\gamma\\) 不敏感——策略改进常在很少几轮内不再变化；值迭代每轮只是一次 backup（\\(O(|S|^2|A|)\\)），轮数却按 \\(1/(1-\\gamma)\\) 放大。大状态空间下实践者取折中：内层评估只跑若干步再改进（修正的策略迭代）。停止判据的折算是易错点：残差 \\(\\|v_k-v_{k-1}\\|\\) 小"),r("strong",null,"不"),E("等于价值误差小，中间差着 \\(\\gamma/(1-\\gamma)\\) 的放大——\\(\\gamma=0.99\\) 时残差 \\(0.01\\) 只保证误差在 \\(1\\) 以内，而 \\(1\\) 的价值误差对视界百步的问题是巨大的。")],-1)),(A(),l(B,null,{default:e(()=>[o(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%AF%8F%E8%BD%AE%E6%88%90%E6%9C%AC%E4%B8%8E%E6%80%BB%E8%BD%AE%E6%95%B0%E7%9A%84%E6%9D%83%E8%A1%A1%22%5D%20--%3E%20PI%5B%22%E7%AD%96%E7%95%A5%E8%BF%AD%E4%BB%A3%22%5D%0A%20%20A%20--%3E%20VI%5B%22%E5%80%BC%E8%BF%AD%E4%BB%A3%22%5D%0A%20%20PI%20--%3E%20P1%5B%22%E8%BD%AE%E5%86%85%EF%BC%9A%E8%A7%A3%20%7CS%7C%20%E5%85%83%E6%96%B9%E7%A8%8B%E7%BB%84%EF%BC%8C%E8%B4%B5%22%5D%0A%20%20PI%20--%3E%20P2%5B%22%E8%BD%AE%E6%95%B0%EF%BC%9A%E5%BE%88%E5%B0%91%EF%BC%8C%E5%AF%B9%20%CE%B3%20%E4%B8%8D%E6%95%8F%E6%84%9F%22%5D%0A%20%20VI%20--%3E%20V1%5B%22%E8%BD%AE%E5%86%85%EF%BC%9A%E4%B8%80%E6%AC%A1%20backup%EF%BC%8C%E4%BE%BF%E5%AE%9C%22%5D%0A%20%20VI%20--%3E%20V2%5B%22%E8%BD%AE%E6%95%B0%EF%BC%9A%E6%8C%89%201%2F(1-%CE%B3)%20%E6%94%BE%E5%A4%A7%22%5D%0A%20%20P2%20--%3E%20MID%5B%22%E6%8A%98%E4%B8%AD%EF%BC%9A%E4%BF%AE%E6%AD%A3%E7%AD%96%E7%95%A5%E8%BF%AD%E4%BB%A3%EF%BC%8C%E5%86%85%E5%B1%82%E5%8F%AA%E8%B7%91%E5%87%A0%E6%AD%A5%22%5D%0A%20%20V2%20--%3E%20MID%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">把残差阈值直接当精度用是最常见的 DP 错误：\\(\\gamma=0.99\\) 时，「相邻两轮差小于 \\(0.01\\)」留给 \\(V^*\\) 的误差上界是 \\(1\\)。阈值必须除以 \\(\\gamma/(1-\\gamma)\\) 再叫精度。</span></p><p>然后是本课真正的转折。整套流程要求 \\(P\\) 与 \\(r\\) <strong>写在手里</strong>：评估要逐状态算 \\(\\sum_{s&#39;}P\\cdot V\\)，改进要逐状态对每个 \\(a\\) 算期望。在语言生成里逐项检查：状态是前缀，数量 \\(|V|^{T}\\) 量级，一张表都存不下；\\(P\\) 是 delta（下一课细说）但 \\(r\\) 依赖外部验证器，回合末才给出、不可枚举。「模型已知」这个在教科书里一行带过的前提，在 LLM 里两项全塌。于是课程转向：只从采样出的轨迹学——无模型。下一课先把生成正式写成 MDP，把「塌在哪」逐项钉死。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不讲异步 DP 与线性规划解法；收敛速度是最坏情形的几何率，实际问题常更快，但拿它报预算是安全的。另外「模型已知但状态太大」与「模型完全未知」是两个缺口：后者才是无模型单元的主题，不过二者共享同一个处境——逐状态 backup 不可用，这就是衔接点。</p><p><span class="marginnote">常见误区：以为这套迭代「慢一点总能用」。它不是慢，是开不了工：\\(P\\) 要逐状态查询、\\(r\\) 要逐动作枚举，而 LLM 的前缀状态连表都存不下。无模型方法因此不是提速优化，而是换前提——从查表改成从采样轨迹里学。</span></p><p>后课默认：评估与改进是两支可分离的迭代，策略迭代有限步收敛，值迭代按 \\(\\gamma\\) 几何收敛。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>策略迭代 = 评估（解 \\(T_\\pi\\) 不动点）+ 改进（贪心），不降价值、有限步终止。</li><li>值迭代 = 直接迭代 \\(T^*\\)，每轮误差乘 \\(\\gamma\\)，阈值要除 \\(\\gamma/(1-\\gamma)\\) 才是精度。</li><li>轮数与每轮成本的权衡：策略迭代轮少步贵，值迭代轮多步贱，折中是修正策略迭代。</li><li>一切前提是 \\(P\\)、\\(r\\) 可逐状态查询；LLM 里状态 \\(|V|^T\\) 量级、奖励在回合末，前提塌方。</li><li>塌方把课程推向无模型：从采样轨迹学，不查表。</li><li>出处：Bellman, <em>Dynamic Programming</em>, 1957；Howard, <em>Dynamic Programming and Markov Processes</em>, 1960；Sutton &amp; Barto 2018 第 4 章。</li></ul>',8))])}const F=n(p,[["render",d]]);export{u as __pageData,F as default};
